            "{\n"
            ".reg .pred ready;\n"
            "DX_BULK_WAIT:\n"
            "mbarrier.try_wait.parity.shared::cta.b64 ready, [%0], %1;\n"
            "@ready bra DX_BULK_DONE;\n"
            "bra DX_BULK_WAIT;\n"
            "DX_BULK_DONE:\n"
            "}\n"
            :: "r"(barrier_shared), "r"(phase) : "memory");
    }
    __syncthreads();
}

